1	import { useState } from "react";
2	import { ScrollText, Clock, ChevronLeft, ChevronRight, Filter } from "lucide-react";
3	import { PageHeader } from "@/components/shared/PageHeader";
4	import { EmptyState } from "@/components/shared/EmptyState";
5	import { Badge } from "@/components/ui/badge";
6	import { Button } from "@/components/ui/button";
7	import { Skeleton } from "@/components/ui/skeleton";
8	import {
9	  Select,
10	  SelectContent,
11	  SelectItem,
12	  SelectTrigger,
13	  SelectValue,
14	} from "@/components/ui/select";
15	import { Card, CardContent } from "@/components/ui/card";
16	import { useAuditLog } from "@/hooks/admin/use-audit-log";
17	import { formatDistanceToNow, format } from "date-fns";
18	
19	const PAGE_SIZE = 25;
20	
21	const ACTION_OPTIONS = [
22	  { value: "", label: "All actions" },
23	  { value: "change_plan", label: "Change Plan" },
24	  { value: "change_role", label: "Change Role" },
25	  { value: "reset_scan_count", label: "Reset Scan Count" },
26	  { value: "ban_user", label: "Ban User" },
27	  { value: "unban_user", label: "Unban User" },
28	];
29	
30	const ACTION_LABELS: Record<string, string> = {
31	  change_plan: "Changed plan",
32	  change_role: "Changed role",
33	  reset_scan_count: "Reset scan count",
34	  ban_user: "Banned user",
35	  unban_user: "Unbanned user",
36	};
37	
38	const ACTION_BADGE_CLASSES: Record<string, string> = {
39	  change_plan: "bg-blue-100 text-blue-700 border-0",
40	  change_role: "bg-purple-100 text-purple-700 border-0",
41	  reset_scan_count: "bg-amber-100 text-amber-700 border-0",
42	  ban_user: "bg-red-100 text-red-700 border-0",
43	  unban_user: "bg-green-100 text-green-700 border-0",
44	};
45	
46	function MetadataPill({ label, value }: { label: string; value: string }) {
47	  return (
48	    <span className="inline-flex items-center gap-1 rounded bg-muted/50 px-1.5 py-0.5 text-[10px] font-medium text-foreground/80">
49	      <span className="text-muted-foreground">{label}:</span>
50	      <span className="capitalize">{String(value).replace("_", " ")}</span>
51	    </span>
52	  );
53	}
54	
55	function LogSkeleton() {
56	  return (
57	    <div className="space-y-3">
58	      {Array.from({ length: 8 }).map((_, i) => (
59	        <div
60	          key={i}
61	          className="flex items-start gap-4 rounded-xl border border-border/50 bg-white p-4"
62	        >
63	          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
64	          <div className="flex-1 space-y-2">
65	            <Skeleton className="h-4 w-64" />
66	            <Skeleton className="h-3 w-40" />
67	          </div>
68	          <Skeleton className="h-4 w-24" />
69	        </div>
70	      ))}
71	    </div>
72	  );
73	}
74	
75	export default function AuditLog() {
76	  const [page, setPage] = useState(0);
77	  const [actionFilter, setActionFilter] = useState("");
78	
79	  const { data, isLoading, isError } = useAuditLog({
80	    page,
81	    pageSize: PAGE_SIZE,
82	    actionFilter: actionFilter || undefined,
83	  });
84	
85	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
86	
87	  return (
88	    <div className="space-y-6">
89	      <PageHeader
90	        title="Audit Log"
91	        description="Chronological record of all admin actions."
92	      />
93	
94	      {/* Filter */}
95	      <div className="flex items-center gap-3">
96	        <Filter className="h-4 w-4 text-muted-foreground" />
97	        <Select
98	          value={actionFilter}
99	          onValueChange={(v) => {
100	            setActionFilter(v);
101	            setPage(0);
102	          }}
103	        >
104	          <SelectTrigger className="w-[180px]" aria-label="Filter by action type">
105	            <SelectValue />
106	          </SelectTrigger>
107	          <SelectContent>
108	            {ACTION_OPTIONS.map((opt) => (
109	              <SelectItem key={opt.value} value={opt.value}>
110	                {opt.label}
111	              </SelectItem>
112	            ))}
113	          </SelectContent>
114	        </Select>
115	        {actionFilter && (
116	          <Button
117	            variant="ghost"
118	            size="sm"
119	            onClick={() => {
120	              setActionFilter("");
121	              setPage(0);
122	            }}
123	          >
124	            Clear filter
125	          </Button>
126	        )}
127	        {data && (
128	          <span className="ml-auto text-sm text-muted-foreground">
129	            {data.total.toLocaleString()} entries
130	          </span>
131	        )}
132	      </div>
133	
134	      {/* Entries */}
135	      {isLoading ? (
136	        <LogSkeleton />
137	      ) : isError ? (
138	        <div
139	          role="alert"
140	          className="rounded-xl border border-red-200 bg-red-50 p-6 text-center text-sm text-red-700"
141	        >
142	          Failed to load audit log. Check your admin permissions.
143	        </div>
144	      ) : data?.entries.length === 0 ? (
145	        <EmptyState
146	          icon={ScrollText}
147	          title="No audit log entries"
148	          description={
149	            actionFilter
150	              ? "No entries match the selected action filter."
151	              : "Admin actions will appear here once they occur."
152	          }
153	        />
154	      ) : (
155	        <ol className="space-y-2.5" aria-label="Audit log entries">
156	          {data?.entries.map((entry) => {
157	            const metadata = entry.metadata as Record<string, string>;
158	            const metaKeys = Object.keys(metadata).filter(
159	              (k) => metadata[k] !== undefined && metadata[k] !== null
160	            );
161	
162	            return (
163	              <li key={entry.id}>
164	                <Card className="border-border/50 shadow-soft hover:border-slate-300 transition-colors">
165	                  <CardContent className="flex items-start gap-4 p-4">
166	                    {/* Icon */}
167	                    <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted/50">
168	                      <ScrollText className="h-4 w-4 text-slate-500" />
169	                    </div>
170	
171	                    {/* Content */}
172	                    <div className="flex-1 min-w-0">
173	                      <div className="flex items-center gap-2 flex-wrap">
174	                        <span className="text-sm font-medium text-foreground">
175	                          {entry.admin_name ?? entry.admin_email ?? entry.admin_id}
176	                        </span>
177	                        <Badge
178	                          className={`text-[10px] px-1.5 py-0 ${
179	                            ACTION_BADGE_CLASSES[entry.action] ??
180	                            "bg-muted/50 text-foreground/80 border-0"
181	                          }`}
182	                        >
183	                          {ACTION_LABELS[entry.action] ?? entry.action}
184	                        </Badge>
185	                      </div>
186	
187	                      {/* Target */}
188	                      {entry.target_id && (
189	                        <p className="mt-0.5 font-mono text-[11px] text-muted-foreground/70">
190	                          Target: {entry.target_type} · {entry.target_id}
191	                        </p>
192	                      )}
193	
194	                      {/* Metadata pills */}
195	                      {metaKeys.length > 0 && (
196	                        <div className="mt-1.5 flex flex-wrap gap-1">
197	                          {metaKeys.map((k) => (
198	                            <MetadataPill
199	                              key={k}
200	                              label={k.replace(/_/g, " ")}
201	                              value={String(metadata[k])}
202	                            />
203	                          ))}
204	                        </div>
205	                      )}
206	                    </div>
207	
208	                    {/* Timestamp */}
209	                    <div className="shrink-0 text-right">
210	                      <div className="flex items-center gap-1 text-xs text-muted-foreground justify-end">
211	                        <Clock className="h-3 w-3" />
212	                        <span title={format(new Date(entry.created_at), "PPpp")}>
213	                          {formatDistanceToNow(new Date(entry.created_at), {
214	                            addSuffix: true,
215	                          })}
216	                        </span>
217	                      </div>
218	                      <p className="mt-0.5 text-[10px] text-muted-foreground/50">
219	                        {format(new Date(entry.created_at), "MMM d, yyyy")}
220	                      </p>
221	                    </div>
222	                  </CardContent>
223	                </Card>
224	              </li>
225	            );
226	          })}
227	        </ol>
228	      )}
229	
230	      {/* Pagination */}
231	      {totalPages > 1 && (
232	        <div className="flex items-center justify-between pt-2">
233	          <p className="text-sm text-muted-foreground">
234	            Page {page + 1} of {totalPages}
235	          </p>
236	          <div className="flex items-center gap-2">
237	            <Button
238	              variant="outline"
239	              size="sm"
240	              onClick={() => setPage((p) => Math.max(0, p - 1))}
241	              disabled={page === 0}
242	              aria-label="Previous page"
243	            >
244	              <ChevronLeft className="h-4 w-4" />
245	            </Button>
246	            <Button
247	              variant="outline"
248	              size="sm"
249	              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
250	              disabled={page >= totalPages - 1}
251	              aria-label="Next page"
252	            >
253	              <ChevronRight className="h-4 w-4" />
254	            </Button>
255	          </div>
256	        </div>
257	      )}
258	    </div>
259	  );
260	}
