1	/**
2	 * Feature Flags page.
3	 *
4	 * Flags are stored in localStorage for now.
5	 * TODO: Move to a `system_config` Supabase table.
6	 *       Migration: CREATE TABLE system_config (key TEXT PRIMARY KEY, value JSONB, updated_at TIMESTAMPTZ DEFAULT NOW());
7	 *       RLS: Only super_admin can read/write.
8	 */
9	
10	import { useState, useCallback } from "react";
11	import { Flag, AlertTriangle, Clock } from "lucide-react";
12	import { PageHeader } from "@/components/shared/PageHeader";
13	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
14	import { Badge } from "@/components/ui/badge";
15	import { Switch } from "@/components/ui/switch";
16	import { Label } from "@/components/ui/label";
17	import { toast } from "sonner";
18	import { format } from "date-fns";
19	
20	// ── Flag definitions ──────────────────────────────────────────
21	
22	interface FeatureFlag {
23	  key: string;
24	  label: string;
25	  description: string;
26	  defaultValue: boolean;
27	  category: "ui" | "feature" | "system";
28	  requiresSuperAdmin?: boolean;
29	}
30	
31	const FLAG_DEFINITIONS: FeatureFlag[] = [
32	  {
33	    key: "agent_hub_enabled",
34	    label: "AI Agent Hub",
35	    description: "Show the AI Agent Hub section in the user sidebar navigation.",
36	    defaultValue: true,
37	    category: "ui",
38	  },
39	  {
40	    key: "integrations_enabled",
41	    label: "Integrations Page",
42	    description:
43	      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
44	    defaultValue: true,
45	    category: "ui",
46	  },
47	  {
48	    key: "pdf_export_enabled",
49	    label: "PDF Export",
50	    description:
51	      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
52	    defaultValue: false,
53	    category: "feature",
54	  },
55	  {
56	    key: "email_notifications_enabled",
57	    label: "Email Notifications",
58	    description:
59	      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
60	    defaultValue: false,
61	    category: "feature",
62	  },
63	  {
64	    key: "free_scan_enabled",
65	    label: "Public Scan (No Auth)",
66	    description:
67	      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
68	    defaultValue: true,
69	    category: "feature",
70	  },
71	  {
72	    key: "maintenance_mode",
73	    label: "Maintenance Mode",
74	    description:
75	      "Show a maintenance banner to all users. Does not block access — visual notice only.",
76	    defaultValue: false,
77	    category: "system",
78	    requiresSuperAdmin: true,
79	  },
80	];
81	
82	const CATEGORY_LABELS: Record<FeatureFlag["category"], string> = {
83	  ui: "UI",
84	  feature: "Feature",
85	  system: "System",
86	};
87	
88	const CATEGORY_BADGE_CLASSES: Record<FeatureFlag["category"], string> = {
89	  ui: "bg-sky-100 text-sky-700 border-0",
90	  feature: "bg-indigo-100 text-indigo-700 border-0",
91	  system: "bg-red-100 text-red-700 border-0",
92	};
93	
94	// ── localStorage helpers ──────────────────────────────────────
95	
96	const LS_KEY = "crobot_feature_flags";
97	
98	interface StoredFlags {
99	  values: Record<string, boolean>;
100	  timestamps: Record<string, number>;
101	}
102	
103	function loadFlags(): StoredFlags {
104	  try {
105	    const raw = localStorage.getItem(LS_KEY);
106	    if (!raw) return { values: {}, timestamps: {} };
107	    return JSON.parse(raw) as StoredFlags;
108	  } catch {
109	    return { values: {}, timestamps: {} };
110	  }
111	}
112	
113	function saveFlags(stored: StoredFlags): void {
114	  localStorage.setItem(LS_KEY, JSON.stringify(stored));
115	}
116	
117	function getFlagValue(stored: StoredFlags, key: string, defaultValue: boolean): boolean {
118	  return key in stored.values ? stored.values[key] : defaultValue;
119	}
120	
121	// ── Main page ─────────────────────────────────────────────────
122	
123	export default function AdminFeatureFlags() {
124	  const [stored, setStored] = useState<StoredFlags>(() => loadFlags());
125	
126	  const handleToggle = useCallback(
127	    (flag: FeatureFlag, enabled: boolean) => {
128	      const next: StoredFlags = {
129	        values: { ...stored.values, [flag.key]: enabled },
130	        timestamps: { ...stored.timestamps, [flag.key]: Date.now() },
131	      };
132	      setStored(next);
133	      saveFlags(next);
134	      toast.success(
135	        `${flag.label} ${enabled ? "enabled" : "disabled"}`
136	      );
137	    },
138	    [stored]
139	  );
140	
141	  const categories: FeatureFlag["category"][] = ["ui", "feature", "system"];
142	
143	  return (
144	    <div className="space-y-8">
145	      <PageHeader
146	        title="Feature Flags"
147	        description="Toggle features on/off across the platform."
148	      />
149	
150	      {/* Local storage warning banner */}
151	      <div
152	        role="alert"
153	        className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3.5"
154	      >
155	        <AlertTriangle className="h-4 w-4 text-amber-500 mt-0.5 shrink-0" />
156	        <div className="flex-1">
157	          <p className="text-sm font-medium text-amber-800">
158	            Flags stored locally
159	          </p>
160	          <p className="text-xs text-amber-700 mt-0.5">
161	            Feature flags are stored in this browser's localStorage only.
162	            {/* TODO: Move to database — migrate system_config table */}
163	            Deploy the{" "}
164	            <code className="font-mono text-[11px] bg-amber-100 px-1 py-0.5 rounded">
165	              system_config
166	            </code>{" "}
167	            database migration for production-wide flag management.
168	          </p>
169	        </div>
170	      </div>
171	
172	      {/* Flags by category */}
173	      {categories.map((category) => {
174	        const flags = FLAG_DEFINITIONS.filter((f) => f.category === category);
175	
176	        return (
177	          <Card key={category} className="border-border/50 shadow-soft">
178	            <CardHeader className="pb-3">
179	              <div className="flex items-center gap-2">
180	                <Flag className="h-4 w-4 text-muted-foreground" />
181	                <CardTitle className="text-base font-semibold capitalize">
182	                  {category === "ui"
183	                    ? "UI Visibility"
184	                    : category === "feature"
185	                    ? "Feature Toggles"
186	                    : "System Flags"}
187	                </CardTitle>
188	              </div>
189	            </CardHeader>
190	            <CardContent className="divide-y divide-slate-100">
191	              {flags.map((flag) => {
192	                const enabled = getFlagValue(stored, flag.key, flag.defaultValue);
193	                const changedAt = stored.timestamps[flag.key];
194	
195	                return (
196	                  <div
197	                    key={flag.key}
198	                    className="flex items-start gap-4 py-4 first:pt-0 last:pb-0"
199	                  >
200	                    {/* Toggle */}
201	                    <div className="pt-0.5">
202	                      <Switch
203	                        id={flag.key}
204	                        checked={enabled}
205	                        onCheckedChange={(v) => handleToggle(flag, v)}
206	                        aria-label={`Toggle ${flag.label}`}
207	                      />
208	                    </div>
209	
210	                    {/* Info */}
211	                    <div className="flex-1 min-w-0">
212	                      <div className="flex items-center gap-2 flex-wrap">
213	                        <Label
214	                          htmlFor={flag.key}
215	                          className="text-sm font-medium cursor-pointer"
216	                        >
217	                          {flag.label}
218	                        </Label>
219	                        <Badge
220	                          className={`text-[10px] px-1.5 py-0 ${
221	                            CATEGORY_BADGE_CLASSES[flag.category]
222	                          }`}
223	                        >
224	                          {CATEGORY_LABELS[flag.category]}
225	                        </Badge>
226	                        {flag.requiresSuperAdmin && (
227	                          <Badge className="bg-red-50 text-red-600 border-red-200 text-[10px] px-1.5 py-0">
228	                            Super Admin
229	                          </Badge>
230	                        )}
231	                      </div>
232	                      <p className="mt-1 text-xs text-muted-foreground leading-relaxed">
233	                        {flag.description}
234	                      </p>
235	                      {changedAt && (
236	                        <div className="mt-1.5 flex items-center gap-1 text-[10px] text-muted-foreground/60">
237	                          <Clock className="h-2.5 w-2.5" />
238	                          <span>
239	                            Last changed{" "}
240	                            {format(new Date(changedAt), "MMM d, yyyy 'at' h:mm a")}
241	                          </span>
242	                        </div>
243	                      )}
244	                    </div>
245	
246	                    {/* Status pill */}
247	                    <div className="shrink-0 pt-0.5">
248	                      <Badge
249	                        className={
250	                          enabled
251	                            ? "bg-green-100 text-green-700 border-0 text-[11px]"
252	                            : "bg-muted/50 text-slate-500 border-0 text-[11px]"
253	                        }
254	                      >
255	                        {enabled ? "On" : "Off"}
256	                      </Badge>
257	                    </div>
258	                  </div>
259	                );
260	              })}
261	            </CardContent>
262	          </Card>
263	        );
264	      })}
265	    </div>
266	  );
267	}
