1	import { useState } from "react";
2	import {
3	  ScanLine,
4	  Search,
5	  ChevronLeft,
6	  ChevronRight,
7	  ExternalLink,
8	  Trash2,
9	  MoreHorizontal,
10	  AlertTriangle,
11	  CheckCircle2,
12	  Clock,
13	  Loader2,
14	  ChevronUp,
15	  ChevronDown,
16	  ChevronsUpDown,
17	} from "lucide-react";
18	import { PageHeader } from "@/components/shared/PageHeader";
19	import { EmptyState } from "@/components/shared/EmptyState";
20	import { KpiCard } from "@/components/shared/KpiCard";
21	import { Input } from "@/components/ui/input";
22	import { Button } from "@/components/ui/button";
23	import { Badge } from "@/components/ui/badge";
24	import { Skeleton } from "@/components/ui/skeleton";
25	import {
26	  Select,
27	  SelectContent,
28	  SelectItem,
29	  SelectTrigger,
30	  SelectValue,
31	} from "@/components/ui/select";
32	import {
33	  Table,
34	  TableBody,
35	  TableCell,
36	  TableHead,
37	  TableHeader,
38	  TableRow,
39	} from "@/components/ui/table";
40	import {
41	  DropdownMenu,
42	  DropdownMenuContent,
43	  DropdownMenuItem,
44	  DropdownMenuSeparator,
45	  DropdownMenuTrigger,
46	} from "@/components/ui/dropdown-menu";
47	import {
48	  AlertDialog,
49	  AlertDialogAction,
50	  AlertDialogCancel,
51	  AlertDialogContent,
52	  AlertDialogDescription,
53	  AlertDialogFooter,
54	  AlertDialogHeader,
55	  AlertDialogTitle,
56	} from "@/components/ui/alert-dialog";
57	import {
58	  useAdminScans,
59	  useAdminScanStats,
60	  useDeleteScan,
61	  type AdminScansFilter,
62	} from "@/hooks/admin/use-admin-scans";
63	import type { ScanRow } from "@/types/database";
64	import type { ScanStatus } from "@/types/index";
65	import { format } from "date-fns";
66	
67	// ── Constants ─────────────────────────────────────────────────
68	
69	const PAGE_SIZE = 25;
70	
71	const STATUS_OPTIONS: { value: ScanStatus | ""; label: string }[] = [
72	  { value: "", label: "All statuses" },
73	  { value: "pending", label: "Pending" },
74	  { value: "analyzing", label: "Analyzing" },
75	  { value: "completed", label: "Completed" },
76	  { value: "failed", label: "Failed" },
77	];
78	
79	const STATUS_BADGE_CLASSES: Record<ScanStatus, string> = {
80	  completed: "bg-green-100 text-green-700 border-0",
81	  failed: "bg-red-100 text-red-700 border-0",
82	  pending: "bg-muted/50 text-foreground/80 border-0",
83	  analyzing: "bg-blue-100 text-blue-700 border-0",
84	};
85	
86	const STATUS_ICONS: Record<ScanStatus, React.ElementType> = {
87	  completed: CheckCircle2,
88	  failed: AlertTriangle,
89	  pending: Clock,
90	  analyzing: Loader2,
91	};
92	
93	type SortableColumn = "created_at" | "overall_score" | "issues_found" | "url" | "status";
94	
95	// ── Sub-components ────────────────────────────────────────────
96	
97	function StatsSkeleton() {
98	  return (
99	    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
100	      {Array.from({ length: 4 }).map((_, i) => (
101	        <Skeleton key={i} className="h-[120px] rounded-xl" />
102	      ))}
103	    </div>
104	  );
105	}
106	
107	function TableSkeleton() {
108	  return (
109	    <>
110	      {Array.from({ length: 8 }).map((_, i) => (
111	        <TableRow key={i}>
112	          {Array.from({ length: 8 }).map((__, j) => (
113	            <TableCell key={j}>
114	              <Skeleton className="h-4 w-full max-w-[120px]" />
115	            </TableCell>
116	          ))}
117	        </TableRow>
118	      ))}
119	    </>
120	  );
121	}
122	
123	function SortIcon({
124	  column,
125	  sortColumn,
126	  sortAsc,
127	}: {
128	  column: SortableColumn;
129	  sortColumn: SortableColumn;
130	  sortAsc: boolean;
131	}) {
132	  if (sortColumn !== column)
133	    return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
