5	// ── Plan prices ───────────────────────────────────────────────
6	// Keep in sync with use-admin-actions.ts plan limits
7	
8	export const PLAN_PRICES: Record<string, number> = {
9	  free: 0,
10	  pro: 49,
11	  agency: 199,
12	};
13	
14	// ── Types ─────────────────────────────────────────────────────
15	
16	export interface PlanDistribution {
17	  free: number;
18	  pro: number;
19	  agency: number;
20	}
21	
22	export interface BillingStats {
23	  mrr: number;
24	  annualProjection: number;
25	  activeSubscriptions: number;
26	  freeUsers: number;
27	  planDistribution: PlanDistribution;
28	}
29	
30	export interface PlanChangeEntry extends AuditLogEntry {
31	  previous_plan?: string;
32	  new_plan?: string;
33	}
