35	// ── Fetch helpers ─────────────────────────────────────────────
36	
37	async function fetchBillingStats(): Promise<BillingStats> {
38	  const { data, error } = await supabase
39	    .from("profiles")
40	    .select("plan");
41	
42	  if (error) throw new Error(error.message);
43	
44	  const profiles = data ?? [];
45	
46	  const planDistribution: PlanDistribution = { free: 0, pro: 0, agency: 0 };
47	
48	  for (const p of profiles) {
49	    const plan = p.plan as keyof PlanDistribution;
50	    if (plan in planDistribution) {
51	      planDistribution[plan]++;
52	    }
53	  }
54	
55	  const mrr =
56	    planDistribution.pro * PLAN_PRICES.pro +
57	    planDistribution.agency * PLAN_PRICES.agency;
58	
59	  const annualProjection = mrr * 12;
60	
61	  const activeSubscriptions = planDistribution.pro + planDistribution.agency;
62	
63	  return {
64	    mrr,
65	    annualProjection,
66	    activeSubscriptions,
67	    freeUsers: planDistribution.free,
68	    planDistribution,
69	  };
70	}
