1	import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import type { ScanRow } from "@/types/database";
4	import type { ScanStatus } from "@/types/index";
5	import { toast } from "sonner";
6	
7	// ── Extended scan row with joined user profile ────────────────
8	
9	export interface AdminScanRow extends ScanRow {
10	  user_email?: string;
11	  user_name?: string;
12	}
13	
14	// ── Filters ───────────────────────────────────────────────────
15	
16	export interface AdminScansFilter {
17	  search?: string;
18	  status?: ScanStatus | "";
19	  scoreLte?: number;
20	  scoreGte?: number;
21	  dateFrom?: string;
22	  dateTo?: string;
23	}
24	
25	export interface AdminScansResult {
26	  scans: AdminScanRow[];
27	  total: number;
28	}
29	
30	// ── Aggregate stats ───────────────────────────────────────────
31	
32	export interface AdminScanStats {
33	  totalScans: number;
34	  avgScore: number;
35	  failedScans: number;
36	  scansToday: number;
37	}
38	
39	// ── Fetch helpers ─────────────────────────────────────────────
40	
41	interface FetchAdminScansParams {
42	  page: number;
43	  pageSize: number;
44	  filter: AdminScansFilter;
45	  sortColumn: keyof ScanRow;
46	  sortAsc: boolean;
47	}
48	
49	async function fetchAdminScans({
50	  page,
51	  pageSize,
52	  filter,
53	  sortColumn,
54	  sortAsc,
55	}: FetchAdminScansParams): Promise<AdminScansResult> {
56	  // Fetch scans with joined profile for user email/name
57	  let query = supabase
58	    .from("scans")
59	    .select(
60	      `
61	      *,
62	      profiles:user_id (
63	        email,
64	        full_name
65	      )
66	    `,
67	      { count: "exact" }
68	    )
69	    .order(sortColumn as string, { ascending: sortAsc });
70	
71	  if (filter.status) {
72	    query = query.eq("status", filter.status);
73	  }
74	
75	  if (filter.scoreGte !== undefined && filter.scoreGte > 0) {
76	    query = query.gte("overall_score", filter.scoreGte);
77	  }
78	
79	  if (filter.scoreLte !== undefined && filter.scoreLte < 100) {
80	    query = query.lte("overall_score", filter.scoreLte);
81	  }
82	
83	  if (filter.dateFrom) {
84	    query = query.gte("created_at", filter.dateFrom);
85	  }
86	
87	  if (filter.dateTo) {
88	    query = query.lte("created_at", filter.dateTo);
89	  }
90	
91	  const from = page * pageSize;
92	  const to = from + pageSize - 1;
93	  query = query.range(from, to);
94	
95	  const { data, count, error } = await query;
96	
97	  if (error) throw new Error(error.message);
98	
99	  const scans: AdminScanRow[] = (data ?? []).map((row) => {
100	    const profileData = row.profiles as
101	      | { email: string; full_name: string | null }
102	      | null;
103	
104	    // Filter search client-side after fetch if needed
105	    return {
106	      id: row.id,
107	      user_id: row.user_id,
108	      url: row.url,
109	      favicon_url: row.favicon_url,
110	      page_title: row.page_title,
111	      page_type: row.page_type,
112	      status: row.status,
113	      overall_score: row.overall_score,
114	      issues_found: row.issues_found,
115	      critical_issues: row.critical_issues,
116	      warnings: row.warnings,
117	      quick_wins: row.quick_wins,
118	      screenshot_url: row.screenshot_url,
119	      device: row.device,
120	      error_message: row.error_message,
121	      created_at: row.created_at,
122	      completed_at: row.completed_at,
123	      user_email: profileData?.email,
124	      user_name: profileData?.full_name ?? undefined,
125	    };
126	  });
127	
128	  // Apply search filter after joining (Supabase can't ilike on joined columns directly)
129	  const filtered = filter.search
130	    ? scans.filter(
131	        (s) =>
132	          s.url.toLowerCase().includes(filter.search!.toLowerCase()) ||
133	          (s.user_email ?? "")
134	            .toLowerCase()
135	            .includes(filter.search!.toLowerCase())
136	      )
137	    : scans;
138	
139	  return {
140	    scans: filtered,
141	    total: filter.search ? filtered.length : (count ?? 0),
142	  };
143	}
144	
145	async function fetchAdminScanStats(): Promise<AdminScanStats> {
146	  const todayStart = new Date();
147	  todayStart.setHours(0, 0, 0, 0);
148	
149	  const [
150	    { count: totalScans, error: totalError },
151	    { count: failedScans, error: failedError },
152	    { count: scansToday, error: todayError },
153	    { data: scoreData, error: scoreError },
154	  ] = await Promise.all([
155	    supabase.from("scans").select("*", { count: "exact", head: true }),
156	    supabase
157	      .from("scans")
158	      .select("*", { count: "exact", head: true })
159	      .eq("status", "failed"),
160	    supabase
161	      .from("scans")
162	      .select("*", { count: "exact", head: true })
163	      .gte("created_at", todayStart.toISOString()),
164	    supabase
165	      .from("scans")
166	      .select("overall_score")
167	      .eq("status", "completed")
168	      .not("overall_score", "is", null),
169	  ]);
170	
171	  if (totalError) throw new Error(totalError.message);
172	  if (failedError) throw new Error(failedError.message);
173	  if (todayError) throw new Error(todayError.message);
174	  if (scoreError) throw new Error(scoreError.message);
175	
176	  const scores = (scoreData ?? [])
177	    .map((r) => r.overall_score as number)
178	    .filter((s) => s !== null);
179	
180	  const avgScore =
181	    scores.length > 0
182	      ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
183	      : 0;
184	
185	  return {
186	    totalScans: totalScans ?? 0,
187	    avgScore,
188	    failedScans: failedScans ?? 0,
189	    scansToday: scansToday ?? 0,
190	  };
191	}
